def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    alive_opponents = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)

    if budget <= 0:
        return 0.0

    if not alive_opponents:
        bid = min(budget, DAILY_SALARY * 0.35)
        return float(max(0.0, bid))

    prev_bids = []
    aggressive_count = 0
    desperate_count = 0
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        bid_y = prev.get('bid')
        if bid_y is not None:
            prev_bids.append(float(bid_y))
            if bid_y >= DAILY_SALARY * 1.1:
                aggressive_count += 1
        if opp.get('hp', 10) <= 2 or opp.get('no_water_days', 0) >= 1:
            desperate_count += 1

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    scarcity = (25.0 - float(supply)) / 10.0
    if scarcity < 0:
        scarcity = 0.0
    if scarcity > 1:
        scarcity = 1.0

    urgency = 0.0
    if hp <= 2:
        urgency += 0.75
    elif hp <= 4:
        urgency += 0.45
    elif hp <= 6:
        urgency += 0.2

    if no_water >= 2:
        urgency += 0.8
    elif no_water >= 1:
        urgency += 0.45

    urgency += scarcity * 0.35
    urgency += desperate_count * 0.08

    if hp >= 7 and no_water == 0 and aggressive_count >= 1:
        base_bid = DAILY_SALARY * (0.18 + 0.10 * scarcity)
    else:
        base_bid = DAILY_SALARY * (0.28 + urgency)

    if highest_prev >= 100 and hp > 4 and no_water == 0:
        base_bid = min(base_bid, DAILY_SALARY * 0.32)
    elif highest_prev > 0 and highest_prev < 60 and urgency > 0.35:
        base_bid = max(base_bid, highest_prev + 2.0)
    elif avg_prev > 0 and avg_prev < 50 and urgency > 0.2:
        base_bid = max(base_bid, avg_prev + 1.5)

    if day >= 8 and hp <= 4:
        base_bid += 8.0

    reserve = DAILY_SALARY * 1.2 if day < 8 else DAILY_SALARY * 0.5
    max_affordable = max(0.0, budget - reserve)
    if hp <= 3 or no_water >= 1:
        max_affordable = budget

    bid = min(base_bid, max_affordable if max_affordable > 0 else budget)

    if hp <= 2 or no_water >= 2:
        bid = max(bid, min(budget, DAILY_SALARY * 0.92))
    elif hp <= 4 and no_water >= 1:
        bid = max(bid, min(budget, DAILY_SALARY * 0.72))

    if bid < 0:
        bid = 0.0
    if bid > budget:
        bid = budget

    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context.get('supply', 0.0))
    day = int(day_context.get('day', 0))

    alive_opps = []
    for opp_id, o in opponents_status.items():
        if o.get('alive', False):
            alive_opps.append((opp_id, o))

    my_hp = float(my_status.get('hp', 0))
    my_budget = float(my_status.get('budget', 0))
    my_no_water_days = int(my_status.get('no_water_days', 0))

    if not alive_opps:
        return min(my_budget, DAILY_SALARY * 0.4)

    # Extract yesterday bids from immediate trace
    prev_bids = []
    for _, o in alive_opps:
        prev = o.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                prev_bids.append(float(b))
            except Exception:
                pass

    highest_prev_bid = max(prev_bids) if prev_bids else 0.0

    # Estimate competition pressure: if others were paying near/above salary, they likely contest aggressively.
    pressure = 0.0
    if highest_prev_bid > 0:
        pressure = min(1.0, highest_prev_bid / (DAILY_SALARY * 1.2))

    # Tight supply increases urgency.
    tightness = 0.0
    if supply <= MIN_SUPPLY:
        tightness = 1.0
    elif supply >= MAX_SUPPLY:
        tightness = 0.0
    else:
        tightness = (MAX_SUPPLY - supply) / float(MAX_SUPPLY - MIN_SUPPLY)
        if tightness < 0.0:
            tightness = 0.0
        if tightness > 1.0:
            tightness = 1.0

    # Base bid: moderate under normal conditions, higher when hp is low or no-water streak grows.
    hp_factor = 1.0
    if my_hp <= 2.0:
        hp_factor = 1.25
    elif my_hp <= 4.0:
        hp_factor = 1.1
    else:
        hp_factor = 0.95

    streak_factor = 1.0
    if my_no_water_days >= 3:
        streak_factor = 1.25
    elif my_no_water_days == 2:
        streak_factor = 1.12

    # Target bid level
    # - If pressure high, move closer to salary to avoid losing the contested allocation.
    # - If pressure low, save budget.
    target = DAILY_SALARY * (0.42 + 0.35 * pressure)  # 0.42..0.77 of salary
    target *= (0.85 + 0.25 * tightness)              # up to ~1.10 when tight
    target *= hp_factor
    target *= streak_factor

    # If yesterday bids were extremely high, bump slightly.
    if highest_prev_bid >= DAILY_SALARY * 0.85:
        target = max(target, highest_prev_bid * 0.85)

    # Safety: never bid more than budget.
    bid = min(my_budget, target)

    # If budget is too low, bid whatever remains but avoid negative.
    if bid < 0.0:
        bid = 0.0

    # Small discrete adjustment to break ties: bid a tiny amount when contest likely.
    if pressure >= 0.6 and bid > 0:
        bid += 1.0

    # Clamp to budget again
    bid = min(bid, my_budget)

    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    DAILY_SALARY = 80
    WATER_REQ = 7
    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    if not alive_opponents:
        return min(my_status['budget'], 20.0)

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    if yesterday_bids:
        avg_bid = sum(yesterday_bids) / len(yesterday_bids)
        target = max(avg_bid * 1.05, 85.0)
    else:
        target = 90.0

    if my_status['hp'] < 4:
        target *= 1.2

    return float(min(my_status['budget'], target))
